import React, { useEffect, useRef, useState } from "react";

import { BUSINESS, SERVICES } from "../content/site";
import { submitLead } from "../lib/lead";

type Props = {
  /** Skips the first step on a service page, where the visitor's interest is already known. */
  project?: string;
};

type Status = "idle" | "sending" | "sent" | "error";

/**
 * Two steps: one easy tap, then contact details. Starting with a question that
 * costs nothing gets more people into the form than opening on six empty fields.
 */
export function LeadForm({ project = "" }: Props) {
  const [projectType, setProjectType] = useState(project);
  const [status, setStatus] = useState<Status>("idle");
  const detailsRef = useRef<HTMLDivElement>(null);
  const movedToDetails = useRef(false);

  useEffect(() => {
    // Keyboard and screen-reader users land on the step they just opened.
    if (projectType && movedToDetails.current) {
      detailsRef.current?.querySelector("input")?.focus();
      movedToDetails.current = false;
    }
  }, [projectType]);

  const choose = (name: string) => {
    movedToDetails.current = true;
    setProjectType(name);
  };

  const handleSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const data = new FormData(event.currentTarget);

    // Bots fill the hidden field; show them success and send nothing.
    if (data.get("website")) {
      setStatus("sent");
      return;
    }

    setStatus("sending");
    try {
      await submitLead({
        name: String(data.get("name") ?? ""),
        email: String(data.get("email") ?? ""),
        phone: String(data.get("phone") ?? ""),
        project_type: projectType,
        message: String(data.get("message") ?? ""),
        smsConsent: data.get("smsConsent") !== null,
      });
      setStatus("sent");
    } catch {
      setStatus("error");
    }
  };

  if (status === "sent") {
    return (
      <div className="lead-form lead-form--done" role="status">
        <p className="eyebrow">Message received</p>
        <h2 className="lead-form__title">Thank You. Your Message Has Been Sent.</h2>
        <p>We'll get back to you within 24 hours.</p>
        <p>
          Need us sooner? Call <a href={BUSINESS.phoneHref}>{BUSINESS.phone}</a>.
        </p>
      </div>
    );
  }

  if (!projectType) {
    return (
      <div className="lead-form">
        <p className="lead-form__step">Step 1 of 2</p>
        <h2 id="lead-form-question" className="lead-form__title">
          What Are You Planning?
        </h2>
        <div className="lead-form__options" role="group" aria-labelledby="lead-form-question">
          {SERVICES.map((service) => (
            <button key={service.slug} type="button" className="lead-form__option" onClick={() => choose(service.name)}>
              {service.name}
              <Arrow />
            </button>
          ))}
        </div>
        <p className="lead-form__note">We'll get back to you within 24 hours.</p>
      </div>
    );
  }

  return (
    <form className="lead-form" onSubmit={handleSubmit}>
      <p className="lead-form__step">{project ? "Schedule a consultation" : "Step 2 of 2"}</p>
      <h2 className="lead-form__title">Where Should We Reach You?</h2>

      <p className="lead-form__chosen">
        <span>{projectType}</span>
        <button type="button" onClick={() => setProjectType("")}>
          Change
        </button>
      </p>

      <div ref={detailsRef} className="lead-form__fields">
        <label className="field">
          <span>Full name</span>
          <input type="text" name="name" autoComplete="name" required />
        </label>
        <label className="field">
          <span>Email address</span>
          <input type="email" name="email" autoComplete="email" required />
        </label>
        <label className="field">
          <span>
            Phone number <em>Optional</em>
          </span>
          <input type="tel" name="phone" autoComplete="tel" inputMode="tel" />
        </label>
        <label className="field field--wide">
          <span>
            Tell us about your project <em>Optional</em>
          </span>
          <textarea name="message" rows={3} />
        </label>
      </div>

      <label className="lead-form__trap" aria-hidden="true">
        Leave this field empty
        <input type="text" name="website" tabIndex={-1} autoComplete="off" />
      </label>

      <label className="lead-form__consent">
        <input type="checkbox" name="smsConsent" required />
        <span>
          I consent to receive SMS/text messages about my inquiry. Message and data rates may apply. I can opt out at
          any time by texting STOP.
        </span>
      </label>

      <button type="submit" className="btn btn--primary btn--block" disabled={status === "sending"}>
        {status === "sending" ? "Sending..." : "Schedule My Consultation"}
        <Arrow />
      </button>

      {status === "error" && (
        <p className="lead-form__error" role="alert">
          Your message didn't go through. Please try again or call <a href={BUSINESS.phoneHref}>{BUSINESS.phone}</a>.
        </p>
      )}

      <p className="lead-form__note">
        We'll use your phone number to send project updates and appointment confirmations via text. Your data is secure
        and will never be shared with third parties.
      </p>
    </form>
  );
}

export function Arrow() {
  return (
    <svg className="arrow" viewBox="0 0 24 12" width="24" height="12" aria-hidden="true">
      <path d="M0 6h22M17 1l5 5-5 5" fill="none" stroke="currentColor" strokeWidth="1.6" />
    </svg>
  );
}
