/**
 * The same LeadConnector webhook and payload the old site posted to, so the
 * client's CRM automation keeps working without changes.
 */
const WEBHOOK_URL =
  "https://services.leadconnectorhq.com/hooks/BkSlXjCtPuurPhRGHs3M/webhook-trigger/dff8d3c9-b572-48d1-a18f-7aa0ce5b48bf";

export type Lead = {
  name: string;
  email: string;
  phone: string;
  project_type: string;
  message: string;
  smsConsent: boolean;
};

export async function submitLead(lead: Lead): Promise<void> {
  const response = await fetch(WEBHOOK_URL, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(lead),
  });

  if (!response.ok) {
    throw new Error(`Lead webhook responded ${response.status}`);
  }
}
